-- CommandProject: in-game cheat menu (generated by the launcher).
-- @KEY@ (or the CP tab on the left edge) opens and closes it. Each click sends the new state to the
-- simulation through SimCallback 'CPCheats'; the simulation ignores it in multiplayer.
local UIUtil = import('/lua/ui/uiutil.lua')
local LayoutHelpers = import('/lua/maui/layouthelpers.lua')
local Bitmap = import('/lua/maui/bitmap.lua').Bitmap

local KEY = '@KEY@'
local SHOW_TAB = @TAB@
local State = {
    Mass = @MASS@,
    Energy = @ENERGY@,
    Research = @RESEARCH@,
    God = @GOD@,
    BuildSpeed = @SPEED@,
    AiToo = @AI@,
}
local SPEEDS = { 1, 2, 5, 10, 25 }

local C_PANEL = 'F00E161E'
local C_HEAD = 'FF15212C'
local C_ROW = 'FF17232F'
local C_HOVER = 'FF23384B'
local C_TEXT = 'FFE6EEF5'
local C_FAINT = 'FF8A97A3'
local C_ON = 'FF63E08E'
local C_ACCENT = 'FFF2B33D'

local panel = false
local tab = false
local rows = {}
local enabled = false

local function Px(n)
    return n * LayoutHelpers.GetPixelScaleFactor()
end

local function Send(extra)
    local args = {
        Mass = State.Mass, Energy = State.Energy, Research = State.Research,
        God = State.God, BuildSpeed = State.BuildSpeed, AiToo = State.AiToo,
    }
    if extra then
        for k, v in extra do args[k] = v end
    end
    SimCallback({ Func = 'CPCheats', Args = args })
end

local function Click()
    pcall(function() PlaySound(Sound({ Bank = 'Interface', Cue = 'UI_Menu_MouseDown' })) end)
end

local function MakeText(parent, text, size, color)
    local t = UIUtil.CreateText(parent, text, size, UIUtil.bodyFont)
    t:SetColor(color or C_TEXT)
    t:DisableHitTest()
    return t
end

local function Refresh()
    for _, row in rows do row:Refresh() end
end

local function OnOff(key)
    return function()
        if State[key] then return 'ON', C_ON end
        return 'OFF', C_FAINT
    end
end

local function Toggler(key)
    return function()
        State[key] = not State[key]
        Send()
    end
end

local function NextSpeed()
    local nextValue = SPEEDS[1]
    for i, v in SPEEDS do
        if v == State.BuildSpeed then
            nextValue = SPEEDS[i + 1] or SPEEDS[1]
            break
        end
        if v > State.BuildSpeed then
            nextValue = v
            break
        end
    end
    State.BuildSpeed = nextValue
    Send()
end

local function SpeedText()
    if State.BuildSpeed <= 1 then return 'NORMAL', C_FAINT end
    return State.BuildSpeed .. 'x', C_ON
end

local function MakeRow(parent, above, label, onClick, valueFn)
    local row = Bitmap(parent)
    row:SetSolidColor(C_ROW)
    row.Width:Set(function() return parent.Width() - Px(16) end)
    row.Height:Set(Px(30))
    if above then
        LayoutHelpers.Below(row, above, 4)
    else
        LayoutHelpers.AtLeftTopIn(row, parent, 8, 52)
    end
    row.label = MakeText(row, label, 14)
    LayoutHelpers.AtLeftIn(row.label, row, 10)
    LayoutHelpers.AtVerticalCenterIn(row.label, row, 0)
    row.value = MakeText(row, '', 13)
    LayoutHelpers.AtRightIn(row.value, row, 10)
    LayoutHelpers.AtVerticalCenterIn(row.value, row, 0)
    row.Refresh = function(self)
        if valueFn then
            local text, color = valueFn()
            self.value:SetText(text)
            self.value:SetColor(color)
        end
    end
    row.HandleEvent = function(self, event)
        if event.Type == 'MouseEnter' then
            self:SetSolidColor(C_HOVER)
            return true
        elseif event.Type == 'MouseExit' then
            self:SetSolidColor(C_ROW)
            return true
        elseif event.Type == 'ButtonPress' or event.Type == 'ButtonDClick' then
            Click()
            onClick()
            Refresh()
            return true
        end
        return false
    end
    row:Refresh()
    table.insert(rows, row)
    return row
end

local function CreatePanel()
    local frame = GetFrame(0)
    panel = Bitmap(frame)
    panel:SetSolidColor(C_PANEL)
    panel.Depth:Set(frame:GetTopmostDepth() + 100)
    panel.Width:Set(Px(300))
    panel.Height:Set(Px(410))
    LayoutHelpers.AtRightIn(panel, frame, 24)
    LayoutHelpers.AtVerticalCenterIn(panel, frame, -40)
    -- clicks on the panel never reach the map below it
    panel.HandleEvent = function(self, event)
        return event.Type == 'ButtonPress' or event.Type == 'ButtonDClick' or event.Type == 'WheelRotation'
    end

    local head = Bitmap(panel)
    head:SetSolidColor(C_HEAD)
    head.Width:Set(panel.Width)
    head.Height:Set(Px(44))
    LayoutHelpers.AtLeftTopIn(head, panel, 0, 0)
    head:DisableHitTest()
    local bar = Bitmap(panel)
    bar:SetSolidColor(C_ACCENT)
    bar.Width:Set(Px(4))
    bar.Height:Set(head.Height)
    LayoutHelpers.AtLeftTopIn(bar, panel, 0, 0)
    bar:DisableHitTest()
    local title = MakeText(head, 'CommandProject - Trapacas', 16, C_ACCENT)
    LayoutHelpers.AtLeftTopIn(title, head, 14, 6)
    local hint = MakeText(head, KEY .. ' abre e fecha', 11, C_FAINT)
    LayoutHelpers.AtLeftTopIn(hint, head, 14, 25)

    local r = MakeRow(panel, nil, 'Massa infinita', Toggler('Mass'), OnOff('Mass'))
    r = MakeRow(panel, r, 'Energia infinita', Toggler('Energy'), OnOff('Energy'))
    r = MakeRow(panel, r, 'Pesquisa infinita', Toggler('Research'), OnOff('Research'))
    r = MakeRow(panel, r, 'Modo deus', Toggler('God'), OnOff('God'))
    r = MakeRow(panel, r, 'Construcao rapida', NextSpeed, SpeedText)
    r = MakeRow(panel, r, 'IA tambem ganha', Toggler('AiToo'), OnOff('AiToo'))
    r = MakeRow(panel, r, 'Liberar toda a pesquisa', function() Send({ UnlockNow = true }) end,
        function() return 'AGORA', C_ACCENT end)
    r = MakeRow(panel, r, 'Desligar tudo', function()
        State.Mass = false
        State.Energy = false
        State.Research = false
        State.God = false
        State.BuildSpeed = 1
        State.AiToo = false
        Send()
    end, nil)
    r = MakeRow(panel, r, 'Fechar', function() Toggle() end, function() return KEY, C_FAINT end)

    local foot = MakeText(panel, 'So vale jogando sozinho contra a IA.', 11, C_FAINT)
    LayoutHelpers.AtLeftIn(foot, panel, 14)
    LayoutHelpers.AtBottomIn(foot, panel, 10)
    panel:Hide()
end

local function CreateTab()
    local frame = GetFrame(0)
    tab = Bitmap(frame)
    tab:SetSolidColor(C_HEAD)
    tab.Depth:Set(frame:GetTopmostDepth() + 90)
    tab.Width:Set(Px(30))
    tab.Height:Set(Px(30))
    LayoutHelpers.AtLeftIn(tab, frame, 0)
    LayoutHelpers.AtVerticalCenterIn(tab, frame, 0)
    local label = MakeText(tab, 'CP', 13, C_ACCENT)
    LayoutHelpers.AtCenterIn(label, tab)
    tab.HandleEvent = function(self, event)
        if event.Type == 'MouseEnter' then
            self:SetSolidColor(C_HOVER)
            return true
        elseif event.Type == 'MouseExit' then
            self:SetSolidColor(C_HEAD)
            return true
        elseif event.Type == 'ButtonPress' then
            Click()
            Toggle()
            return true
        end
        return false
    end
end

local function BindKey()
    pcall(function()
        IN_AddKeyMapTable({
            [KEY] = { action = 'UI_Lua import("/lua/ui/game/cp_cheatmenu.lua").Toggle()', category = 'ui', order = 99 },
        })
    end)
end

function Toggle()
    if not enabled then return end
    if not panel then CreatePanel() end
    if panel:IsHidden() then
        Refresh()
        panel:Show()
    else
        panel:Hide()
    end
end

local function HumanCount()
    local n = 0
    local ok, info = pcall(GetArmiesTable)
    if ok and info and info.armiesTable then
        for _, army in info.armiesTable do
            if army.human then n = n + 1 end
        end
    end
    return n
end

function Init(isReplay)
    if isReplay or GetFocusArmy() == -1 or HumanCount() > 1 then return end
    enabled = true
    BindKey()
    -- the game may reload the key map after the interface is built: bind again a little later
    ForkThread(function()
        WaitSeconds(3)
        BindKey()
        WaitSeconds(10)
        BindKey()
    end)
    if SHOW_TAB then pcall(CreateTab) end
end
